class Solution {
  public int numberOfCleanRooms(int[][] room) {
    int m = room.length, n = room[0].length;
    int[] dr = {0, 1, 0, -1}, dc = {1, 0, -1, 0};
    boolean[][][] seen = new boolean[m][n][4];
    boolean[][] cleaned = new boolean[m][n];
    int r = 0, c = 0, d = 0, count = 0;
    while (!seen[r][c][d]) {
      seen[r][c][d] = true;
      if (!cleaned[r][c]) {
        cleaned[r][c] = true;
        count++;
      }
      int nr = r + dr[d], nc = c + dc[d];
      if (nr >= 0 && nr < m && nc >= 0 && nc < n && room[nr][nc] == 0) {
        r = nr;
        c = nc;
      } else {
        d = (d + 1) % 4;
      }
    }
    return count;
  }
}
